+            'password' => 'password',
+            'name' => 'Impersonator Update Test',
+        ]);
+        $this->assertEquals(201, $user['headers']['status-code']);
+        $userId = $user['body']['$id'];
+
+        $this->assertFalse($user['body']['impersonator'] ?? false);
